// Une la consulta normalizada con el stock leído de Google Sheets
const consulta = $('Validar datos de entrada').first().json;
const filas = $input.all().map(i => i.json).filter(r => r && r.sku && !r.error);
const stockOk = filas.length > 0;
const stockTexto = stockOk
  ? filas.map(r => `${r.sku} | ${r.marca} ${r.modelo} | ${r.medida} | ${r.tipo_vehiculo} | ${r.indice_carga}${r.indice_velocidad} | S/ ${r.precio_soles} | stock: ${r.stock}`).join('\n')
  : 'SIN DATOS DE STOCK: la fuente no respondió. No cotices.';
return [{ json: { ...consulta, stock_disponible: stockOk, filas_stock: filas, stock_texto: stockTexto } }];

