// Guardarraíl: nada se ejecuta sobre datos reales sin pasar por aquí
const c = $('Preparar contexto').first().json;
const item = $input.first().json;
const DECISIONES = ['RESPONDER', 'COTIZAR', 'GARANTIA', 'DERIVAR_HUMANO', 'FUERA_DE_ALCANCE'];
let o = item.output;
let forzado = '';
let errorDetalle = '';

if (item.error || o === undefined || o === null || o === '') {
  forzado = 'fallo_o_respuesta_nula_llm';
  errorDetalle = typeof item.error === 'string' ? item.error : JSON.stringify(item.error || 'output vacío');
} else if (typeof o === 'string') {
  try { o = JSON.parse(o); } catch (e) { forzado = 'json_invalido'; }
}
if (!forzado && !DECISIONES.includes(o.decision)) forzado = 'decision_invalida';
if (!forzado && !String(o.respuesta_cliente || '').trim()) forzado = 'respuesta_vacia';
const conf = Number(o?.confianza);
if (!forzado && (isNaN(conf) || conf < 0.7) && !['DERIVAR_HUMANO', 'FUERA_DE_ALCANCE'].includes(o.decision)) forzado = 'confianza_baja';

// Cotización: cada SKU debe existir en la hoja Stock y tener stock suficiente; el precio sale de la hoja, no del LLM
let productos = [];
let total = 0;
if (!forzado && o.decision === 'COTIZAR') {
  const stock = c.filas_stock || [];
  for (const p of (o.productos || [])) {
    const fila = stock.find(r => String(r.sku).trim() === String(p.sku).trim());
    const cant = Math.max(1, parseInt(p.cantidad) || 1);
    if (!fila || Number(fila.stock) < cant) { forzado = 'cotizacion_no_verificable'; break; }
    const precio = Number(fila.precio_soles);
    productos.push({ sku: fila.sku, producto: `${fila.marca} ${fila.modelo} ${fila.medida}`, cantidad: cant, precio_unitario: precio, subtotal: precio * cant });
    total += precio * cant;
  }
  if (!forzado && productos.length === 0) forzado = 'cotizacion_sin_productos';
}

const saludo = c.nombre ? `Hola ${c.nombre}` : 'Hola';
const final = forzado
  ? { decision: 'DERIVAR_HUMANO', confianza: 0, motivo: `Forzado por validación: ${forzado}`,
      respuesta_cliente: `${saludo}, gracias por escribirnos. Un asesor de RutaSur Neumáticos revisará su consulta personalmente y le responderá a la brevedad en horario de atención (lunes a sábado de 8:00 a 18:00).\n\nEquipo RutaSur Neumáticos`,
      datos_garantia: {}, fuentes: [] }
  : o;

const g = final.datos_garantia || {};
return [{ json: {
  execution_id: $execution.id,
  fecha: $now.toFormat('yyyy-MM-dd HH:mm:ss'),
  canal: c.canal, nombre: c.nombre, email: c.email, mensaje: c.mensaje, asunto: c.asunto, message_id: c.message_id,
  decision: final.decision, confianza: Number(final.confianza) || 0, motivo: final.motivo,
  respuesta_cliente: final.respuesta_cliente,
  productos, productos_texto: productos.map(p => `${p.cantidad} x ${p.producto} (${p.sku}) @ S/ ${p.precio_unitario}`).join('; '),
  total_soles: total,
  garantia_producto: g.producto || '', garantia_fecha_compra: g.fecha_compra || '',
  garantia_comprobante: g.comprobante || '', garantia_falla: g.descripcion_falla || '',
  fuentes: (final.fuentes || []).join(', '),
  forzado_por_validacion: forzado || 'no',
  error_detalle: errorDetalle,
  cotizacion_id: `COT-${$execution.id}`, ticket_id: `GAR-${$execution.id}`, derivacion_id: `DER-${$execution.id}`,
  valida_hasta: $now.plus({ days: 7 }).toFormat('yyyy-MM-dd'),
} }];
